package org.jsoup.parser;

import org.junit.Test;
import static org.junit.Assert.*;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class TokenQueue_ESTest_test28 extends TokenQueue_ESTest_scaffolding {

    /**
     * consumeCssIdentifier() reads an identifier off the queue and stops at the first
     * character that is not part of a CSS ident (here, the space before "(").
     * Per the CSS spec, a NULL character (U+0000) embedded in the identifier is replaced
     * with the REPLACEMENT CHARACTER (U+FFFD), so "b�L" is decoded as "b�L".
     */
    @Test(timeout = 4000)
    public void consumeCssIdentifier_replacesNullWithReplacementChar_andStopsAtSpace() throws Throwable {
        TokenQueue tokenQueue = new TokenQueue("b\\u0000L (");

        String identifier = tokenQueue.consumeCssIdentifier();

        assertEquals("b\\uFFFDL", identifier);
    }
}
